package com.tradeledger;

import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.Locale;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.widgets.Widget;

/**
 * Displays estimated FIFO profit on the GE sell-offer total line.
 * All widget operations must occur on the RuneLite client thread.
 */
@Slf4j
public final class GeOfferProfit
{
    // Confirmed from the user's GE widget diagnostics.
    private static final int OFFER_GROUP = 465;
    private static final int OFFER_PARENT_CHILD = 26;
    private static final int ITEM_CHILD = 23;
    private static final int OFFER_TYPE_CHILD = 20;
    private static final int TOTAL_CHILD = 45;

    // Geometry adjustments are applied only when multiline is enabled.
    private static final int EXTRA_HEIGHT = 15;
    private static final int MOVE_UP = 5;

    private static final Pattern NET_TOTAL = Pattern.compile(
        "^\\s*([\\d,]+)\\s+coins?\\b", Pattern.CASE_INSENSITIVE);
    private static final Pattern OUR_SUFFIX = Pattern.compile(
        "(?s)(?:<br>|\\s+)\\s*<col=(?:00ff00|ff4040|ffff00)>"
            + "(?:Expected )?Profit:.*$", Pattern.CASE_INSENSITIVE);

    private final Client client;
    private final TradeLedgerStorage storage;
    private final TradeLedgerConfig config;

    private Widget lastTotalWidget;
    private int originalHeight;
    private int originalY;
    private boolean geometryChanged;

    public GeOfferProfit(Client client, TradeLedgerStorage storage, TradeLedgerConfig config)
    {
        this.client = client;
        this.storage = storage;
        this.config = config;
    }

    public void update()
    {
        Widget parent = client.getWidget(OFFER_GROUP, OFFER_PARENT_CHILD);
        Widget type = child(parent, OFFER_TYPE_CHILD);
        Widget item = child(parent, ITEM_CHILD);
        Widget total = child(parent, TOTAL_CHILD);

        if (parent == null || parent.isHidden() || type == null || item == null
            || total == null || total.isHidden()
            || !"Sell offer".equalsIgnoreCase(clean(type.getText()).trim())
            || item.getItemId() <= 0 || item.getItemQuantity() <= 0)
        {
            clear();
            return;
        }

        if (total != lastTotalWidget)
        {
            clear();
            lastTotalWidget = total;
            originalHeight = total.getOriginalHeight();
            originalY = total.getOriginalY();
            geometryChanged = false;
        }

        String currentText = total.getText();
        if (currentText == null)
        {
            clear();
            return;
        }

        // The GE's clientscript can replace the text whenever the price or
        // quantity changes. Strip only our own suffix and preserve its value.
        String baseText = OUR_SUFFIX.matcher(currentText).replaceFirst("");
        Matcher totalMatcher = NET_TOTAL.matcher(clean(baseText));
        if (!totalMatcher.find())
        {
            restoreTextOnly(total, baseText);
            return;
        }

        final long proceeds;
        try
        {
            proceeds = Long.parseLong(totalMatcher.group(1).replace(",", ""));
        }
        catch (NumberFormatException ex)
        {
            restoreTextOnly(total, baseText);
            return;
        }

        int itemId = item.getItemId();
        int quantity = item.getItemQuantity();
        Long cost = calculateFifoCost(itemId, quantity);
        if (cost == null)
        {
            restoreTextOnly(total, baseText);
            return;
        }

        long profit = proceeds - cost;
        String color = profit > 0 ? "00ff00" : profit < 0 ? "ff4040" : "ffff00";
        String amount = String.format(Locale.US, "%,d", profit);
        String value = profit > 0 ? "+" + amount : amount;
        boolean multiline = config.multilineProfit();
        String separator = multiline ? "<br>" : " ";
        String desired = baseText + separator + "<col=" + color
            + ">Profit: " + value + " GP</col>";

        if (!multiline)
        {
            restoreGeometry(total);
        }
        else if (!geometryChanged)
        {
            total.setOriginalHeight(originalHeight + EXTRA_HEIGHT);
            total.setOriginalY(originalY - MOVE_UP);
            total.revalidate();
            geometryChanged = true;
        }
        if (!desired.equals(currentText))
        {
            total.setText(desired);
        }
    }

    /**
     * Allocate cost from oldest non-canceled purchases first. Uses the same
     * integer cost allocation as TradeTransaction.getRemainingCost(), so
     * partial sales of uneven unit costs do not introduce rounding drift.
     */
    private Long calculateFifoCost(int itemId, int quantity)
    {
        final List<TradeTransaction> purchases;
        try
        {
            purchases = new ArrayList<>(storage.load().purchases);
        }
        catch (RuntimeException ex)
        {
            log.warn("Could not load recorded purchases for GE profit estimate", ex);
            return null;
        }

        purchases.sort(Comparator.comparing(TradeTransaction::getBoughtAt));
        int needed = quantity;
        long cost = 0;
        for (TradeTransaction purchase : purchases)
        {
            if (purchase.getItemId() != itemId || !purchase.isIncludedInOverview())
            {
                continue;
            }
            int available = purchase.getQuantityRemaining();
            if (available <= 0)
            {
                continue;
            }
            int take = Math.min(needed, available);
            long remainingAfter = purchase.getTotalCost()
                * (available - take) / purchase.getQuantityBought();
            cost += purchase.getRemainingCost() - remainingAfter;
            needed -= take;
            if (needed == 0)
            {
                return cost;
            }
        }
        return null;
    }

    private static Widget child(Widget parent, int index)
    {
        if (parent == null)
        {
            return null;
        }
        Widget[] children = parent.getChildren();
        return children != null && index < children.length ? children[index] : null;
    }

    private static String clean(String value)
    {
        return value == null ? "" : value.replaceAll("<[^>]*>", "");
    }

    private void restoreTextOnly(Widget widget, String baseText)
    {
        if (!baseText.equals(widget.getText()))
        {
            widget.setText(baseText);
        }
        restoreGeometry(widget);
    }

    private void restoreGeometry(Widget widget)
    {
        if (geometryChanged && widget != null)
        {
            widget.setOriginalHeight(originalHeight);
            widget.setOriginalY(originalY);
            widget.revalidate();
            geometryChanged = false;
        }
    }

    private void clear()
    {
        if (lastTotalWidget != null)
        {
            String text = lastTotalWidget.getText();
            if (text != null)
            {
                String base = OUR_SUFFIX.matcher(text).replaceFirst("");
                if (!base.equals(text))
                {
                    lastTotalWidget.setText(base);
                }
            }
            restoreGeometry(lastTotalWidget);
        }
        lastTotalWidget = null;
    }

    public void reset()
    {
        clear();
    }
}

package com.tradeledger;

import com.google.gson.Gson;
import java.util.HashMap;
import java.util.Map;
import java.util.HashSet;
import java.util.Set;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.GrandExchangeOffer;
import net.runelite.api.GrandExchangeOfferState;
import net.runelite.api.events.GrandExchangeOfferChanged;
import net.runelite.client.config.ConfigManager;

/**
 * Watches cumulative GE offer updates and emits only newly filled sell quantities.
 * Per-slot checkpoints are persisted in the current RuneScape profile to avoid
 * replaying the same fill when the client or plugin restarts.
 */
@Slf4j
public final class GeSaleWatcher
{
    private static final String GROUP = "tradeledger";
    private static final String PREFIX = "geSaleCheckpointV1_";
    private static final int MAX_SLOTS = 8;

    private final ConfigManager configManager;
    private final Gson gson;
    private final Map<Integer, Checkpoint> checkpoints = new HashMap<>();
    private final Set<Integer> seenNonEmptyThisSession = new HashSet<>();

    @Inject
    public GeSaleWatcher(ConfigManager configManager, Gson gson)
    {
        this.configManager = configManager;
        this.gson = gson;
    }

    public void resetMemory()
    {
        checkpoints.clear();
        seenNonEmptyThisSession.clear();
    }

    public SaleFill observe(GrandExchangeOfferChanged event)
    {
        int slot = event.getSlot();
        if (slot < 0 || slot >= MAX_SLOTS)
        {
            return null;
        }

        GrandExchangeOffer offer = event.getOffer();
        if (offer == null)
        {
            return null;
        }

        GrandExchangeOfferState state = offer.getState();
        if (state == GrandExchangeOfferState.EMPTY)
        {
            // Login initialization can emit EMPTY for every slot before the
            // server supplies real offers. Preserve persisted checkpoints until
            // this slot has actually shown a nonempty offer in this session.
            if (!seenNonEmptyThisSession.remove(slot))
            {
                return null;
            }
            checkpoints.remove(slot);
            configManager.unsetRSProfileConfiguration(GROUP, PREFIX + slot);
            return null;
        }

        seenNonEmptyThisSession.add(slot);

        if (state != GrandExchangeOfferState.SELLING
            && state != GrandExchangeOfferState.SOLD
            && state != GrandExchangeOfferState.CANCELLED_SELL)
        {
            // Buy offers don't produce sale fills, and replacing an offer
            // invalidates any old sell checkpoint for the slot.
            checkpoints.remove(slot);
            configManager.unsetRSProfileConfiguration(GROUP, PREFIX + slot);
            return null;
        }

        Checkpoint current = new Checkpoint();
        current.itemId = offer.getItemId();
        current.offerPrice = offer.getPrice();
        current.totalQuantity = offer.getTotalQuantity();
        current.filledQuantity = offer.getQuantitySold();
        current.grossTotal = offer.getSpent();

        if (current.itemId <= 0 || current.totalQuantity <= 0
            || current.filledQuantity < 0 || current.grossTotal < 0)
        {
            return null;
        }

        Checkpoint previous = checkpoints.get(slot);
        if (previous == null)
        {
            String saved = configManager.getRSProfileConfiguration(GROUP, PREFIX + slot);
            if (saved != null)
            {
                try
                {
                    previous = gson.fromJson(saved, Checkpoint.class);
                }
                catch (RuntimeException ex)
                {
                    log.warn("Invalid saved GE slot checkpoint {}", slot, ex);
                }
            }
        }

        boolean sameOffer = previous != null
            && previous.itemId == current.itemId
            && previous.offerPrice == current.offerPrice
            && previous.totalQuantity == current.totalQuantity
            && previous.filledQuantity <= current.filledQuantity
            && previous.grossTotal <= current.grossTotal;

        // A new or unrecognized offer starts at its observed baseline. We
        // deliberately don't claim historical fills we cannot distinguish.
        if (!sameOffer)
        {
            store(slot, current);
            return null;
        }

        int deltaQuantity = current.filledQuantity - previous.filledQuantity;
        long deltaGross = current.grossTotal - previous.grossTotal;
        if (deltaQuantity <= 0 || deltaGross <= 0)
        {
            if (deltaQuantity != 0 || deltaGross != 0)
            {
                store(slot, current);
            }
            return null;
        }

        store(slot, current);
        return new SaleFill(current.itemId, deltaQuantity, deltaGross);
    }

    private void store(int slot, Checkpoint checkpoint)
    {
        checkpoints.put(slot, checkpoint);
        configManager.setRSProfileConfiguration(GROUP, PREFIX + slot, gson.toJson(checkpoint));
    }

    private static final class Checkpoint
    {
        private int itemId;
        private long offerPrice;
        private int totalQuantity;
        private int filledQuantity;
        private long grossTotal;
    }

    public static final class SaleFill
    {
        public final int itemId;
        public final int quantity;
        public final long gross;

        private SaleFill(int itemId, int quantity, long gross)
        {
            this.itemId = itemId;
            this.quantity = quantity;
            this.gross = gross;
        }
    }
}

package com.tradeledger;

import java.time.LocalDateTime;
import java.util.Objects;

public final class HistoryTrade
{
    public enum Kind { BOUGHT, SOLD }

    private final Kind kind;
    private final int itemId;
    private final String itemName;
    private final int quantity;
    private final long netAmount;
    private final long grossAmount;
    private final long tax;
    private final LocalDateTime recordedAt;

    public HistoryTrade(Kind kind, int itemId, String itemName, int quantity,
                        long netAmount, long grossAmount, long tax, LocalDateTime recordedAt)
    {
        this.kind = Objects.requireNonNull(kind);
        this.itemId = itemId;
        this.itemName = Objects.requireNonNull(itemName);
        this.quantity = quantity;
        this.netAmount = netAmount;
        this.grossAmount = grossAmount;
        this.tax = tax;
        this.recordedAt = Objects.requireNonNull(recordedAt);
        if (itemId <= 0 || quantity <= 0 || netAmount < 0 || grossAmount < 0 || tax < 0
            || (kind == Kind.BOUGHT && (grossAmount != netAmount || tax != 0))
            || (kind == Kind.SOLD && grossAmount - tax != netAmount))
        {
            throw new IllegalArgumentException("Invalid history transaction");
        }
    }

    // GE history doesn't provide a stable transaction ID. Identical trades are ambiguous.
    public String getSignature()
    {
        return kind + ":" + itemId + ":" + quantity + ":" + netAmount + ":" + grossAmount + ":" + tax;
    }

    public Kind getKind() { return kind; }
    public int getItemId() { return itemId; }
    public String getItemName() { return itemName; }
    public int getQuantity() { return quantity; }
    public long getNetAmount() { return netAmount; }
    public long getGrossAmount() { return grossAmount; }
    public long getTax() { return tax; }
    public LocalDateTime getRecordedAt() { return recordedAt; }
}

package com.tradeledger;

import java.time.LocalDateTime;

public final class RecordedSale
{
    private final HistoryTrade trade;
    private String note = "";

    public RecordedSale(HistoryTrade trade)
    {
        if (trade.getKind() != HistoryTrade.Kind.SOLD)
        {
            throw new IllegalArgumentException("Expected a sale");
        }
        this.trade = trade;
    }

    public HistoryTrade getTrade() { return trade; }
    public LocalDateTime getRecordedAt() { return trade.getRecordedAt(); }
    public String getNote() { return note; }
    public void setNote(String note) { this.note = note == null ? "" : note; }
}

package com.tradeledger;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.GridLayout;
import java.time.format.DateTimeFormatter;
import java.util.Locale;
import javax.swing.BorderFactory;
import javax.swing.JLabel;
import javax.swing.JMenuItem;
import javax.swing.JPanel;
import javax.swing.JPopupMenu;
import javax.swing.SwingConstants;
import net.runelite.client.game.ItemManager;
import net.runelite.client.util.AsyncBufferedImage;

public class RecordedSaleCard extends JPanel
{
    private static final Color BACKGROUND = new Color(43, 43, 43);
    private static final Color TEXT = new Color(220, 220, 220);
    private static final Color ACCENT = new Color(235, 180, 65);

    public RecordedSaleCard(RecordedSale sale, ItemManager itemManager,
                            Runnable deleteAction, Runnable noteAction)
    {
        HistoryTrade trade = sale.getTrade();
        setLayout(new BorderLayout(9, 8));
        setBackground(BACKGROUND);
        setBorder(BorderFactory.createCompoundBorder(
            BorderFactory.createLineBorder(ACCENT),
            BorderFactory.createEmptyBorder(10, 8, 10, 8)));
        setAlignmentX(LEFT_ALIGNMENT);
        setMaximumSize(new Dimension(Integer.MAX_VALUE, 310));

        JLabel icon = new JLabel();
        AsyncBufferedImage image = itemManager.getImage(trade.getItemId());
        if (image != null)
        {
            image.addTo(icon);
        }
        icon.setVerticalAlignment(SwingConstants.TOP);
        add(icon, BorderLayout.WEST);

        JPanel content = new JPanel(new GridLayout(0, 1, 0, 5));
        content.setOpaque(false);
        add(content, BorderLayout.CENTER);

        addLabel(content, trade.getItemName(), Color.WHITE, true);
        addLabel(content, "SOLD · UNMATCHED", ACCENT, true);
        addLabel(content, "Recorded: " + trade.getRecordedAt().format(
            DateTimeFormatter.ofPattern("dd MMM yyyy, HH:mm", Locale.ENGLISH)), TEXT, false);
        addLabel(content, "Quantity: " + format(trade.getQuantity()), TEXT, false);
        addLabel(content, "Gross sale: " + format(trade.getGrossAmount()) + " GP", TEXT, false);
        addLabel(content, "GE tax: " + format(trade.getTax()) + " GP", TEXT, false);
        addLabel(content, "Net received: " + format(trade.getNetAmount()) + " GP", Color.WHITE, true);
        addLabel(content, "Profit: not calculated (purchase not linked)", TEXT, false);
        if (!sale.getNote().isEmpty())
        {
            addLabel(content, "Note: " + sale.getNote(), TEXT, false);
        }

        JPopupMenu menu = new JPopupMenu();
        JMenuItem note = new JMenuItem("Edit note");
        note.addActionListener(event -> noteAction.run());
        menu.add(note);
        JMenuItem delete = new JMenuItem("Remove from history");
        delete.addActionListener(event -> deleteAction.run());
        menu.add(delete);
        setComponentPopupMenu(menu);
        content.setComponentPopupMenu(menu);
        icon.setComponentPopupMenu(menu);
        for (java.awt.Component child : content.getComponents())
        {
            if (child instanceof javax.swing.JComponent)
            {
                ((javax.swing.JComponent) child).setComponentPopupMenu(menu);
            }
        }
    }

    private static void addLabel(JPanel panel, String text, Color color, boolean bold)
    {
        JLabel label = new JLabel(text);
        label.setForeground(color);
        if (bold)
        {
            TradeLedgerFonts.bold(label);
        }
        else
        {
            TradeLedgerFonts.regular(label);
        }
        panel.add(label);
    }

    private static String format(long value)
    {
        return String.format(Locale.US, "%,d", value);
    }
}

package com.tradeledger;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup("tradeledger")
public interface TradeLedgerConfig extends Config
{
    @ConfigItem(
        keyName = "multilineProfit",
        name = "Multiline profit display",
        description = "Show the estimated profit below the GE sell total instead of on the same line",
        position = 0
    )
    default boolean multilineProfit()
    {
        return false;
    }
    @ConfigItem(
        keyName = "showGpInvested",
        name = "Show GP Invested",
        description = "Show the purchase cost of remaining unsold items",
        position = 1
    )
    default boolean showGpInvested() { return true; }

    @ConfigItem(
        keyName = "showRealizedProfit",
        name = "Show Realized profit",
        description = "Show realized profit from matched sales",
        position = 2
    )
    default boolean showRealizedProfit() { return true; }

    @ConfigItem(
        keyName = "showItemsRemaining",
        name = "Show Items remaining",
        description = "Show the total number of unsold recorded items",
        position = 3
    )
    default boolean showItemsRemaining() { return true; }

    @ConfigItem(
        keyName = "showTradeCounts",
        name = "Show Open / completed",
        description = "Show the number of open and completed purchases",
        position = 4
    )
    default boolean showTradeCounts() { return true; }
}

package com.tradeledger;

import java.awt.Font;
import javax.swing.JComponent;

public final class TradeLedgerFonts
{
    public static final float FONT_SIZE = 16.0f;
    public static final float STATUS_SIZE = 23.0f;

    private TradeLedgerFonts()
    {
    }

    public static void regular(JComponent component)
    {
        component.setFont(
                component.getFont().deriveFont(
                        Font.PLAIN,
                        FONT_SIZE
                )
        );
    }

    public static void bold(JComponent component)
    {
        component.setFont(
                component.getFont().deriveFont(
                        Font.BOLD,
                        FONT_SIZE
                )
        );
    }
}

package com.tradeledger;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Component;
import java.awt.Container;
import java.awt.Dimension;
import java.awt.GridLayout;
import java.time.LocalDateTime;
import java.time.format.DateTimeFormatter;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.Locale;
import javax.swing.BorderFactory;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.JButton;
import javax.swing.JComboBox;
import javax.swing.JLabel;
import javax.swing.ImageIcon;
import javax.swing.JOptionPane;
import javax.swing.JPanel;
import javax.swing.SwingConstants;
import net.runelite.client.game.ItemManager;
import net.runelite.client.util.AsyncBufferedImage;
import net.runelite.client.ui.PluginPanel;

public class TradeLedgerPanel extends PluginPanel
{
    private static final Color BACKGROUND = new Color(36, 36, 36);
    private static final Color SECONDARY = new Color(190, 190, 190);
    private static final Color PROFIT_COLOR = new Color(80, 190, 95);
    private static final Color LOSS_COLOR = new Color(210, 80, 80);

    private static final DateTimeFormatter DATE_FORMAT =
            DateTimeFormatter.ofPattern("dd MMM yyyy, HH:mm", Locale.ENGLISH);

    private final ItemManager itemManager;
    private final List<TradeTransaction> transactions = new ArrayList<>();
    private final List<RecordedSale> recordedSales = new ArrayList<>();
    private final TradeLedgerStorage storage;
    private final TradeLedgerConfig config;

    private final JPanel overviewPanel = new JPanel();
    private final JPanel cardsPanel = new JPanel();

    private final JComboBox<String> filterBox = new JComboBox<>(
            new String[]
                    {
                            "All trades",
                            "Open",
                            "Completed",
                            "Canceled"
                    }
    );

    public TradeLedgerPanel(ItemManager itemManager, TradeLedgerStorage storage, TradeLedgerConfig config)
    {
        super();

        this.itemManager = itemManager;
        this.storage = storage;
        this.config = config;
        TradeLedgerStorage.LoadedData saved = storage.load();
        transactions.addAll(saved.purchases);
        recordedSales.addAll(saved.sales);

        setBackground(BACKGROUND);
        setLayout(new BoxLayout(this, BoxLayout.Y_AXIS));
        setBorder(BorderFactory.createEmptyBorder(10, 7, 10, 7));

        buildInterface();
        refresh();
    }

    @Override
    public void onActivate()
    {
        refresh();
    }

    @Override
    public void onDeactivate()
    {
    }

    private void buildInterface()
    {
        JLabel title = new JLabel("Trade Ledger");
        title.setForeground(Color.WHITE);
        title.setAlignmentX(LEFT_ALIGNMENT);
        TradeLedgerFonts.regular(title);

        add(title);
        add(Box.createVerticalStrut(7));

        JLabel subtitle = new JLabel("Grand Exchange trading overview");
        subtitle.setForeground(SECONDARY);
        subtitle.setAlignmentX(LEFT_ALIGNMENT);
        TradeLedgerFonts.regular(subtitle);

        add(subtitle);
        add(Box.createVerticalStrut(14));

        add(createSectionTitle("Overview"));
        add(Box.createVerticalStrut(10));

        overviewPanel.setOpaque(false);
        overviewPanel.setLayout(new GridLayout(0, 1, 0, 8));
        overviewPanel.setAlignmentX(LEFT_ALIGNMENT);
        overviewPanel.setMaximumSize(
                new Dimension(Integer.MAX_VALUE, 340)
        );

        add(overviewPanel);
        add(Box.createVerticalStrut(15));

        JPanel managementPanel = new JPanel();
        managementPanel.setOpaque(false);
        managementPanel.setLayout(
                new BoxLayout(managementPanel, BoxLayout.Y_AXIS)
        );
        managementPanel.setAlignmentX(LEFT_ALIGNMENT);

        JButton clearButton = new JButton("Clear history");
        TradeLedgerFonts.regular(clearButton);
        clearButton.setAlignmentX(LEFT_ALIGNMENT);
        clearButton.setMaximumSize(
                new Dimension(Integer.MAX_VALUE, 42)
        );
        clearButton.setToolTipText("Delete all transaction records");
        clearButton.addActionListener(event -> clearHistory());

        JButton recalculateButton = new JButton("Recalculate");
        TradeLedgerFonts.regular(recalculateButton);
        recalculateButton.setAlignmentX(LEFT_ALIGNMENT);
        recalculateButton.setMaximumSize(
                new Dimension(Integer.MAX_VALUE, 42)
        );
        recalculateButton.setToolTipText(
                "Rebuild the overview from the transaction records"
        );
        recalculateButton.addActionListener(event -> refresh());

        managementPanel.add(clearButton);
        managementPanel.add(Box.createVerticalStrut(6));
        managementPanel.add(recalculateButton);

        add(managementPanel);
        add(Box.createVerticalStrut(20));

        JLabel tradesTitle = createSectionTitle("Trades");
        add(tradesTitle);
        add(Box.createVerticalStrut(8));

        filterBox.setAlignmentX(LEFT_ALIGNMENT);
        filterBox.setMaximumSize(
                new Dimension(Integer.MAX_VALUE, 38)
        );
        TradeLedgerFonts.regular(filterBox);
        filterBox.addActionListener(event -> refreshCards());

        add(filterBox);
        add(Box.createVerticalStrut(12));

        cardsPanel.setOpaque(false);
        cardsPanel.setLayout(new BoxLayout(cardsPanel, BoxLayout.Y_AXIS));
        cardsPanel.setAlignmentX(LEFT_ALIGNMENT);

        add(cardsPanel);
    }

    private JLabel createSectionTitle(String title)
    {
        JLabel label = new JLabel(title);
        label.setForeground(Color.WHITE);
        label.setAlignmentX(LEFT_ALIGNMENT);
        TradeLedgerFonts.regular(label);
        return label;
    }

    private JPanel createOverviewRow(
            String label,
            String value,
            Color color)
    {
        JPanel panel = new JPanel();
        panel.setLayout(new BoxLayout(panel, BoxLayout.Y_AXIS));
        panel.setBackground(new Color(43, 43, 43));
        panel.setBorder(
                BorderFactory.createCompoundBorder(
                        BorderFactory.createLineBorder(new Color(70, 70, 70)),
                        BorderFactory.createEmptyBorder(10, 10, 10, 10)
                )
        );

        JLabel labelComponent = new JLabel(label);
        labelComponent.setForeground(SECONDARY);
        labelComponent.setAlignmentX(LEFT_ALIGNMENT);
        TradeLedgerFonts.regular(labelComponent);

        JLabel valueComponent = new JLabel(value);
        valueComponent.setForeground(color);
        valueComponent.setAlignmentX(LEFT_ALIGNMENT);
        TradeLedgerFonts.bold(valueComponent);

        panel.add(labelComponent);
        panel.add(Box.createVerticalStrut(5));
        panel.add(valueComponent);

        return panel;
    }

    public void refreshOverviewSettings()
    {
        refreshOverview();
    }

    /**
     * Match a newly filled GE sale to the oldest open recorded purchases.
     * Gross proceeds are exact offer deltas. Tax is an estimate because
     * GrandExchangeOfferChanged does not expose the tax actually deducted.
     * Returns the number of sold items successfully matched to purchases.
     */
    public int recordSaleFill(int itemId, int quantity, long gross)
    {
        if (itemId <= 0 || quantity <= 0 || gross <= 0)
        {
            return 0;
        }

        List<TradeTransaction> eligible = new ArrayList<>();
        for (TradeTransaction transaction : transactions)
        {
            if (transaction.getItemId() == itemId
                && transaction.getStatus() == TradeTransaction.Status.OPEN
                && transaction.getQuantityRemaining() > 0)
            {
                eligible.add(transaction);
            }
        }
        eligible.sort(Comparator.comparing(TradeTransaction::getBoughtAt));

        int available = 0;
        for (TradeTransaction transaction : eligible)
        {
            available += transaction.getQuantityRemaining();
        }
        int matched = Math.min(quantity, available);
        if (matched == 0)
        {
            return 0;
        }

        // Allocate only the proportion of proceeds belonging to tracked items.
        long trackedGross = gross * matched / quantity;
        long trackedTax = estimateTax(trackedGross, matched);
        int remaining = matched;
        long assignedGross = 0;
        long assignedTax = 0;
        LocalDateTime timestamp = LocalDateTime.now();

        for (TradeTransaction transaction : eligible)
        {
            if (remaining == 0)
            {
                break;
            }
            int take = Math.min(remaining, transaction.getQuantityRemaining());
            int alreadyAssignedQuantity = matched - remaining;
            int newAssignedQuantity = alreadyAssignedQuantity + take;
            long cumulativeGross = trackedGross * newAssignedQuantity / matched;
            long cumulativeTax = trackedTax * newAssignedQuantity / matched;
            long partGross = cumulativeGross - assignedGross;
            long partTax = cumulativeTax - assignedTax;

            transaction.recordSaleTotals(take, partGross, partTax, timestamp);
            assignedGross = cumulativeGross;
            assignedTax = cumulativeTax;
            remaining -= take;
        }

        persist();
        refresh();
        return matched;
    }

    private static long estimateTax(long gross, int quantity)
    {
        if (gross <= 0 || quantity <= 0)
        {
            return 0;
        }
        // GE tax is 2% of execution price, capped at 5m per item.
        // The offer API supplies only aggregate gross, so this is an estimate.
        long average = gross / quantity;
        long perItemTax = Math.min(5_000_000L, average / 50L);
        return Math.min(gross, perItemTax * quantity);
    }

    private void refresh()
    {
        refreshOverview();
        refreshCards();
    }

    private void refreshOverview()
    {
        long invested = 0;
        long realizedProfit = 0;
        long inventoryQuantity = 0;
        int openTrades = 0;
        int completedTrades = 0;

        for (TradeTransaction transaction : transactions)
        {
            if (!transaction.isIncludedInOverview())
            {
                continue;
            }

            invested += transaction.getRemainingCost();
            realizedProfit += transaction.getRealizedProfit();
            inventoryQuantity += transaction.getQuantityRemaining();

            if (transaction.getStatus() == TradeTransaction.Status.OPEN)
            {
                openTrades++;
            }
            else if (
                    transaction.getStatus() == TradeTransaction.Status.COMPLETED)
            {
                completedTrades++;
            }
        }

        overviewPanel.removeAll();

        if (config.showGpInvested())
        {
            overviewPanel.add(createOverviewRow("GP Invested", formatGp(invested), Color.WHITE));
        }
        if (config.showRealizedProfit())
        {
            overviewPanel.add(createOverviewRow("Realized profit", formatSignedGp(realizedProfit),
                realizedProfit >= 0 ? PROFIT_COLOR : LOSS_COLOR));
        }
        if (config.showItemsRemaining())
        {
            overviewPanel.add(createOverviewRow("Items remaining", formatNumber(inventoryQuantity), Color.WHITE));
        }
        if (config.showTradeCounts())
        {
            overviewPanel.add(createOverviewRow("Open / completed",
                openTrades + " / " + completedTrades, Color.WHITE));
        }

        overviewPanel.revalidate();
        overviewPanel.repaint();
    }

    private void refreshCards()
    {
        cardsPanel.removeAll();
        String selectedFilter = (String) filterBox.getSelectedItem();
        List<Object> visible = new ArrayList<>();

        for (TradeTransaction transaction : transactions)
        {
            if (matchesFilter(transaction, selectedFilter))
            {
                visible.add(transaction);
            }
        }
        if (selectedFilter == null || "All trades".equals(selectedFilter))
        {
            visible.addAll(recordedSales);
        }

        visible.sort((a, b) ->
        {
            LocalDateTime timeA = a instanceof TradeTransaction
                ? ((TradeTransaction) a).getLastActivityAt()
                : ((RecordedSale) a).getRecordedAt();
            LocalDateTime timeB = b instanceof TradeTransaction
                ? ((TradeTransaction) b).getLastActivityAt()
                : ((RecordedSale) b).getRecordedAt();
            return timeB.compareTo(timeA);
        });

        if (visible.isEmpty())
        {
            JLabel emptyLabel = new JLabel("No transactions to display.");
            emptyLabel.setForeground(SECONDARY);
            emptyLabel.setAlignmentX(LEFT_ALIGNMENT);
            TradeLedgerFonts.regular(emptyLabel);
            cardsPanel.add(emptyLabel);
        }
        else
        {
            for (Object record : visible)
            {
                if (record instanceof TradeTransaction)
                {
                    TradeTransaction transaction = (TradeTransaction) record;
                    TransactionCard card = new TransactionCard(
                        transaction,
                        itemManager,
                        () -> cancelTrade(transaction),
                        () -> restoreTrade(transaction),
                        () -> deleteTrade(transaction),
                        () -> editNote(transaction),
                        () -> showDetails(transaction),
                        null
                    );
                    bindPurchaseIcon(card, transaction.getItemId());
                    cardsPanel.add(card);
                }
                else
                {
                    RecordedSale sale = (RecordedSale) record;
                    cardsPanel.add(new RecordedSaleCard(sale, itemManager,
                        () -> deleteSale(sale), () -> editSaleNote(sale)));
                }
                cardsPanel.add(Box.createVerticalStrut(10));
            }
        }

        cardsPanel.revalidate();
        cardsPanel.repaint();
        revalidate();
        repaint();
    }

    /**
     * The existing TransactionCard constructs its icon before the asynchronous
     * item sprite necessarily finishes loading. Bind the sprite to that same
     * label so RuneLite repaints it as soon as it is ready.
     *
     * This avoids changing the established card layout or interaction logic.
     */
    private void bindPurchaseIcon(TransactionCard card, int itemId)
    {
        JLabel iconLabel = findItemIconLabel(card);
        if (iconLabel == null)
        {
            return;
        }

        AsyncBufferedImage image = itemManager.getImage(itemId);
        if (image != null)
        {
            image.addTo(iconLabel);
        }
    }

    private JLabel findItemIconLabel(Container container)
    {
        // TransactionCard puts its icon in BorderLayout.WEST.
        if (container.getLayout() instanceof BorderLayout)
        {
            BorderLayout layout = (BorderLayout) container.getLayout();
            Component west = layout.getLayoutComponent(BorderLayout.WEST);
            if (west instanceof JLabel && ((JLabel) west).getIcon() instanceof ImageIcon)
            {
                return (JLabel) west;
            }
        }

        for (Component component : container.getComponents())
        {
            if (component instanceof JLabel
                && ((JLabel) component).getIcon() instanceof ImageIcon)
            {
                return (JLabel) component;
            }
            if (component instanceof Container)
            {
                JLabel found = findItemIconLabel((Container) component);
                if (found != null)
                {
                    return found;
                }
            }
        }
        return null;
    }

    private boolean matchesFilter(
            TradeTransaction transaction,
            String filter)
    {
        if (filter == null || filter.equals("All trades"))
        {
            return true;
        }

        switch (filter)
        {
            case "Open":
                return transaction.getStatus()
                        == TradeTransaction.Status.OPEN;

            case "Completed":
                return transaction.getStatus()
                        == TradeTransaction.Status.COMPLETED;

            case "Canceled":
                return transaction.getStatus()
                        == TradeTransaction.Status.CANCELED;

            default:
                return true;
        }
    }

    private void cancelTrade(TradeTransaction transaction)
    {
        int answer = JOptionPane.showConfirmDialog(
                this,
                "Cancel tracking for " + transaction.getItemName() + "?\n\n"
                        + "The record will remain in history, but its values\n"
                        + "will be excluded from the overview.\n"
                        + "You can restore it later.",
                "Cancel trade",
                JOptionPane.YES_NO_OPTION,
                JOptionPane.WARNING_MESSAGE
        );

        if (answer == JOptionPane.YES_OPTION)
        {
            transaction.cancel();
            persist();
            refresh();
        }
    }

    private void restoreTrade(TradeTransaction transaction)
    {
        transaction.restore();
        persist();
        refresh();
    }

    private void deleteTrade(TradeTransaction transaction)
    {
        int answer = JOptionPane.showConfirmDialog(
                this,
                "Permanently delete this " + transaction.getItemName()
                        + " trade?\n\nThis cannot be undone.",
                "Remove from history",
                JOptionPane.YES_NO_OPTION,
                JOptionPane.WARNING_MESSAGE
        );

        if (answer == JOptionPane.YES_OPTION)
        {
            transactions.remove(transaction);
            persist();
            refresh();
        }
    }

    private void clearHistory()
    {
        if (transactions.isEmpty() && recordedSales.isEmpty())
        {
            JOptionPane.showMessageDialog(
                    this,
                    "The transaction history is already empty.",
                    "Trade Ledger",
                    JOptionPane.INFORMATION_MESSAGE
            );
            return;
        }

        int answer = JOptionPane.showConfirmDialog(
                this,
                "Delete all " + (transactions.size() + recordedSales.size())
                        + " transaction records?\n\n"
                        + "This cannot be undone.",
                "Clear all history",
                JOptionPane.YES_NO_OPTION,
                JOptionPane.WARNING_MESSAGE
        );

        if (answer == JOptionPane.YES_OPTION)
        {
            transactions.clear();
            recordedSales.clear();
            persist();
            refresh();
        }
    }

    private void editNote(TradeTransaction transaction)
    {
        String newNote = JOptionPane.showInputDialog(
                this,
                "Note for " + transaction.getItemName() + ":",
                transaction.getNote()
        );

        if (newNote != null)
        {
            transaction.setNote(newNote);
            persist();
            refreshCards();
        }
    }

    private void showDetails(TradeTransaction transaction)
    {
        StringBuilder details = new StringBuilder();

        details.append("Item: ")
                .append(transaction.getItemName()).append("\n");

        details.append("Status: ")
                .append(transaction.getStatus()).append("\n");

        details.append("Bought: ")
                .append(transaction.getBoughtAt().format(DATE_FORMAT))
                .append("\n");

        details.append("Last activity: ")
                .append(transaction.getLastActivityAt().format(DATE_FORMAT))
                .append("\n");

        details.append("Quantity bought: ")
                .append(formatNumber(transaction.getQuantityBought()))
                .append("\n");

        details.append("Quantity sold: ")
                .append(formatNumber(transaction.getQuantitySold()))
                .append("\n");

        details.append("Quantity remaining: ")
                .append(formatNumber(transaction.getQuantityRemaining()))
                .append("\n");

        details.append("Buy price: ")
                .append(formatGp(transaction.getBuyPrice()))
                .append("\n");

        details.append("Total purchase cost: ")
                .append(formatGp(transaction.getTotalCost()))
                .append("\n");

        details.append("Sale revenue: ")
                .append(formatGp(transaction.getSaleRevenue()))
                .append("\n");

        details.append("GE tax recorded: ")
                .append(formatGp(transaction.getSaleTax()))
                .append("\n");

        details.append("Realized profit: ")
                .append(formatSignedGp(transaction.getRealizedProfit()))
                .append("\n");

        if (transaction.getLastSoldAt() != null)
        {
            details.append("Last sale: ")
                    .append(transaction.getLastSoldAt().format(DATE_FORMAT))
                    .append("\n");
        }

        if (!transaction.getNote().isEmpty())
        {
            details.append("\nNote: ").append(transaction.getNote());
        }

        JOptionPane.showMessageDialog(
                this,
                details.toString(),
                "Trade details",
                JOptionPane.INFORMATION_MESSAGE
        );
    }

    public void recordHistoryTrade(HistoryTrade trade)
    {
        for (TradeTransaction existing : transactions)
        {
            if (trade.getSignature().equals(existing.getSourceKey()))
            {
                JOptionPane.showMessageDialog(this,
                    "This purchase appears to have already been recorded.\n"
                    + "Identical historical trades cannot be distinguished reliably.",
                    "Trade already recorded", JOptionPane.INFORMATION_MESSAGE);
                return;
            }
        }
        for (RecordedSale existing : recordedSales)
        {
            if (trade.getSignature().equals(existing.getTrade().getSignature()))
            {
                JOptionPane.showMessageDialog(this,
                    "This sale appears to have already been recorded.\n"
                    + "Identical historical trades cannot be distinguished reliably.",
                    "Trade already recorded", JOptionPane.INFORMATION_MESSAGE);
                return;
            }
        }

        if (trade.getKind() == HistoryTrade.Kind.BOUGHT)
        {
            int averagePrice = (int) Math.min(Integer.MAX_VALUE,
                trade.getNetAmount() / trade.getQuantity());
            TradeTransaction transaction = new TradeTransaction(
                trade.getItemId(), trade.getItemName(), trade.getQuantity(),
                averagePrice, trade.getNetAmount(), trade.getRecordedAt());
            transaction.setSourceKey(trade.getSignature());
            transactions.add(transaction);
        }
        else
        {
            recordedSales.add(new RecordedSale(trade));
        }
        filterBox.setSelectedItem("All trades");
        persist();
        refresh();
    }

    private void deleteSale(RecordedSale sale)
    {
        int answer = JOptionPane.showConfirmDialog(this,
            "Remove this " + sale.getTrade().getItemName() + " sale from history?",
            "Remove sale", JOptionPane.YES_NO_OPTION, JOptionPane.WARNING_MESSAGE);
        if (answer == JOptionPane.YES_OPTION)
        {
            recordedSales.remove(sale);
            persist();
            refresh();
        }
    }

    private void editSaleNote(RecordedSale sale)
    {
        String note = JOptionPane.showInputDialog(this,
            "Note for " + sale.getTrade().getItemName() + ":", sale.getNote());
        if (note != null)
        {
            sale.setNote(note);
            persist();
            refreshCards();
        }
    }

    private void persist()
    {
        storage.save(transactions, recordedSales);
    }

    private String formatNumber(long number)
    {
        return String.format(Locale.US, "%,d", number);
    }

    private String formatGp(long amount)
    {
        return formatNumber(amount) + " GP";
    }

    private String formatSignedGp(long amount)
    {
        return (amount >= 0 ? "+" : "") + formatGp(amount);
    }
}

package com.tradeledger;

import com.google.inject.Provides;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.time.LocalDateTime;
import java.util.ArrayList;
import java.util.List;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import javax.inject.Inject;
import javax.swing.SwingUtilities;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.events.GrandExchangeOfferChanged;
import net.runelite.client.events.ConfigChanged;
import net.runelite.api.MenuAction;
import net.runelite.api.MenuEntry;
import net.runelite.api.events.MenuOpened;
import net.runelite.api.events.GameTick;
import net.runelite.api.widgets.Widget;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.game.ItemManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;

@Slf4j
@PluginDescriptor(name = "Trade Ledger", description = "Track Grand Exchange trades and flipping profits")
public class TradeLedgerPlugin extends Plugin
{
    // Verified from GE history diagnostic: parent widget 25100291, six children per row.
    private static final int HISTORY_WIDGET_ID = 25100291;
    private static final int ROW_SIZE = 6;
    private static final Pattern AMOUNT_PATTERN = Pattern.compile("([\\d,]+)\\s+coins?");
    private static final Pattern TAX_PATTERN = Pattern.compile("\\(([\\d,]+)\\s*-\\s*([\\d,]+)\\)");

    @Inject private Client client;
    @Inject private ClientToolbar clientToolbar;
    @Inject private ItemManager itemManager;
    @Inject private TradeLedgerConfig config;
    @Inject private TradeLedgerStorage storage;
    @Inject private GeSaleWatcher saleWatcher;

    private TradeLedgerPanel panel;
    private NavigationButton navigationButton;
    private GeOfferProfit offerProfit;
    private final List<GeSaleWatcher.SaleFill> pendingSales = new ArrayList<>();

    @Override
    protected void startUp()
    {
        log.info("Trade Ledger started");
        offerProfit = new GeOfferProfit(client, storage, config);
        saleWatcher.resetMemory();
        SwingUtilities.invokeLater(() ->
        {
            panel = new TradeLedgerPanel(itemManager, storage, config);
            synchronized (pendingSales)
            {
                for (GeSaleWatcher.SaleFill fill : pendingSales)
                {
                    applySaleFill(fill);
                }
                pendingSales.clear();
            }
            navigationButton = NavigationButton.builder()
                .tooltip("Trade Ledger")
                .icon(createIcon())
                .panel(panel)
                .build();
            clientToolbar.addNavigation(navigationButton);
        });
    }

    @Override
    protected void shutDown()
    {
        synchronized (pendingSales)
        {
            pendingSales.clear();
        }
        if (offerProfit != null)
        {
            offerProfit.reset();
            offerProfit = null;
        }
        SwingUtilities.invokeLater(() ->
        {
            if (navigationButton != null)
            {
                clientToolbar.removeNavigation(navigationButton);
                navigationButton = null;
            }
            panel = null;
        });
    }

    @Subscribe
    public void onConfigChanged(ConfigChanged event)
    {
        if (!"tradeledger".equals(event.getGroup()))
        {
            return;
        }
        SwingUtilities.invokeLater(() ->
        {
            if (panel != null)
            {
                panel.refreshOverviewSettings();
            }
        });
    }

    @Subscribe
    public void onGrandExchangeOfferChanged(GrandExchangeOfferChanged event)
    {
        // During login the client can temporarily clear all GE slots.
        if (client.getGameState() != GameState.LOGGED_IN)
        {
            return;
        }
        GeSaleWatcher.SaleFill fill = saleWatcher.observe(event);
        if (fill == null)
        {
            return;
        }
        SwingUtilities.invokeLater(() ->
        {
            synchronized (pendingSales)
            {
                if (panel == null)
                {
                    pendingSales.add(fill);
                }
                else
                {
                    applySaleFill(fill);
                }
            }
        });
    }

    private void applySaleFill(GeSaleWatcher.SaleFill fill)
    {
        int matched = panel.recordSaleFill(fill.itemId, fill.quantity, fill.gross);
        if (matched < fill.quantity)
        {
            log.info("GE sale for item {}: matched {} of {} items; the rest had no recorded purchase",
                fill.itemId, matched, fill.quantity);
        }
    }

    @Subscribe
    public void onGameTick(GameTick event)
    {
        if (offerProfit != null)
        {
            offerProfit.update();
        }
    }

    @Subscribe
    public void onMenuOpened(MenuOpened event)
    {
        MenuEntry selected = null;
        for (MenuEntry entry : event.getMenuEntries())
        {
            if (entry.getParam1() == HISTORY_WIDGET_ID
                && entry.getParam0() >= 0
                && entry.getParam0() % ROW_SIZE == 0
                && "Buy-offer".equals(entry.getOption()))
            {
                selected = entry;
                break;
            }
        }
        if (selected == null)
        {
            return;
        }

        final int rowStart = selected.getParam0();
        final String target = selected.getTarget();
        client.getMenu().createMenuEntry(-1)
            .setOption("Record Trade")
            .setTarget(target)
            .setType(MenuAction.RUNELITE)
            .onClick(clicked -> recordSelectedRow(rowStart));
    }

    private void recordSelectedRow(int rowStart)
    {
        try
        {
            HistoryTrade trade = readHistoryRow(rowStart);
            if (trade == null)
            {
                log.warn("Could not read GE history row {}", rowStart / ROW_SIZE);
                return;
            }
            log.info("Recording {} {} x {}: net={}, gross={}, tax={}",
                trade.getKind(), trade.getQuantity(), trade.getItemName(),
                trade.getNetAmount(), trade.getGrossAmount(), trade.getTax());
            SwingUtilities.invokeLater(() ->
            {
                if (panel != null)
                {
                    panel.recordHistoryTrade(trade);
                }
            });
        }
        catch (RuntimeException ex)
        {
            log.error("Failed to record GE history entry", ex);
        }
    }

    private HistoryTrade readHistoryRow(int rowStart)
    {
        Widget parent = client.getWidget(HISTORY_WIDGET_ID);
        if (parent == null)
        {
            return null;
        }
        Widget[] children = parent.getChildren();
        if (children == null || rowStart < 0 || rowStart + 5 >= children.length)
        {
            return null;
        }
        Widget action = children[rowStart];
        Widget typeWidget = children[rowStart + 2];
        Widget nameWidget = children[rowStart + 3];
        Widget itemWidget = children[rowStart + 4];
        Widget valueWidget = children[rowStart + 5];
        if (action == null || typeWidget == null || nameWidget == null
            || itemWidget == null || valueWidget == null)
        {
            return null;
        }

        String typeText = stripTags(typeWidget.getText()).trim();
        HistoryTrade.Kind kind;
        if ("Bought:".equals(typeText))
        {
            kind = HistoryTrade.Kind.BOUGHT;
        }
        else if ("Sold:".equals(typeText))
        {
            kind = HistoryTrade.Kind.SOLD;
        }
        else
        {
            return null;
        }

        int itemId = itemWidget.getItemId();
        int quantity = itemWidget.getItemQuantity();
        String name = stripTags(nameWidget.getText()).split("\\n", 2)[0].trim();
        if (name.isEmpty())
        {
            name = stripTags(action.getName()).trim();
        }
        String valueText = stripTags(valueWidget.getText());
        Matcher amountMatcher = AMOUNT_PATTERN.matcher(valueText);
        if (!amountMatcher.find())
        {
            return null;
        }
        long net = parseAmount(amountMatcher.group(1));
        long gross = net;
        long tax = 0;
        if (kind == HistoryTrade.Kind.SOLD)
        {
            Matcher taxMatcher = TAX_PATTERN.matcher(valueText);
            if (taxMatcher.find())
            {
                gross = parseAmount(taxMatcher.group(1));
                tax = parseAmount(taxMatcher.group(2));
            }
        }
        if (name.isEmpty() || itemId <= 0 || quantity <= 0)
        {
            return null;
        }
        return new HistoryTrade(kind, itemId, name, quantity, net, gross, tax, LocalDateTime.now());
    }

    private static long parseAmount(String value)
    {
        return Long.parseLong(value.replace(",", ""));
    }

    private static String stripTags(String value)
    {
        if (value == null)
        {
            return "";
        }
        return value.replaceAll("(?i)<br\\s*/?>", "\n").replaceAll("<[^>]*>", "");
    }

    private BufferedImage createIcon()
    {
        BufferedImage image = new BufferedImage(16, 16, BufferedImage.TYPE_INT_ARGB);
        Graphics2D graphics = image.createGraphics();
        try
        {
            graphics.setColor(Color.WHITE);
            graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
            graphics.drawRoundRect(2, 1, 11, 14, 2, 2);
            graphics.drawLine(5, 5, 11, 5);
            graphics.drawLine(5, 8, 11, 8);
            graphics.drawLine(5, 11, 9, 11);
        }
        finally
        {
            graphics.dispose();
        }
        return image;
    }

    @Provides
    TradeLedgerConfig provideConfig(ConfigManager configManager)
    {
        return configManager.getConfig(TradeLedgerConfig.class);
    }
}

package com.tradeledger;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import java.time.LocalDateTime;
import java.util.List;
import java.util.ArrayList;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.config.ConfigManager;

@Slf4j
public class TradeLedgerStorage
{
    private static final String GROUP = "tradeledger";
    private static final String KEY = "recordedTradesV1";
    private final ConfigManager configManager;
    private final Gson gson;

    @Inject
    public TradeLedgerStorage(ConfigManager configManager, Gson gson)
    {
        this.configManager = configManager;
        this.gson = gson;
    }

    public LoadedData load()
    {
        List<TradeTransaction> purchases = new ArrayList<>();
        List<RecordedSale> sales = new ArrayList<>();
        String raw = configManager.getConfiguration(GROUP, KEY);
        if (raw == null || raw.isEmpty())
        {
            return new LoadedData(purchases, sales);
        }
        try
        {
            JsonObject root = new JsonParser().parse(raw).getAsJsonObject();
            JsonArray buys = root.getAsJsonArray("purchases");
            if (buys != null)
            {
                for (JsonElement element : buys)
                {
                    try
                    {
                        JsonObject o = element.getAsJsonObject();
                        TradeTransaction t = new TradeTransaction(
                            o.get("itemId").getAsInt(), o.get("name").getAsString(),
                            o.get("quantity").getAsInt(), o.get("unitPrice").getAsInt(),
                            o.get("totalCost").getAsLong(), LocalDateTime.parse(o.get("recordedAt").getAsString()));
                        t.setSourceKey(o.get("signature").getAsString());
                        t.restoreRecordedState(o.get("soldQuantity").getAsInt(),
                            o.get("saleRevenue").getAsLong(), o.get("saleTax").getAsLong(),
                            parseOptionalTime(o, "lastSoldAt"), parseOptionalTime(o, "lastActivityAt"),
                            o.get("canceled").getAsBoolean(), o.get("note").getAsString());
                        purchases.add(t);
                    }
                    catch (RuntimeException ex)
                    {
                        log.warn("Skipping invalid saved purchase", ex);
                    }
                }
            }
            JsonArray savedSales = root.getAsJsonArray("sales");
            if (savedSales != null)
            {
                for (JsonElement element : savedSales)
                {
                    try
                    {
                        JsonObject o = element.getAsJsonObject();
                        HistoryTrade trade = new HistoryTrade(HistoryTrade.Kind.SOLD,
                            o.get("itemId").getAsInt(), o.get("name").getAsString(),
                            o.get("quantity").getAsInt(), o.get("net").getAsLong(),
                            o.get("gross").getAsLong(), o.get("tax").getAsLong(),
                            LocalDateTime.parse(o.get("recordedAt").getAsString()));
                        RecordedSale sale = new RecordedSale(trade);
                        sale.setNote(o.get("note").getAsString());
                        sales.add(sale);
                    }
                    catch (RuntimeException ex)
                    {
                        log.warn("Skipping invalid saved sale", ex);
                    }
                }
            }
        }
        catch (RuntimeException ex)
        {
            log.error("Could not read Trade Ledger saved data; leaving it untouched", ex);
            throw new IllegalStateException("Could not load saved Trade Ledger data", ex);
        }
        return new LoadedData(purchases, sales);
    }

    private static LocalDateTime parseOptionalTime(JsonObject object, String key)
    {
        JsonElement value = object.get(key);
        return value == null || value.isJsonNull() ? null : LocalDateTime.parse(value.getAsString());
    }

    public void save(List<TradeTransaction> purchases, List<RecordedSale> sales)
    {
        JsonObject root = new JsonObject();
        JsonArray buys = new JsonArray();
        for (TradeTransaction t : purchases)
        {
            JsonObject o = new JsonObject();
            o.addProperty("itemId", t.getItemId());
            o.addProperty("name", t.getItemName());
            o.addProperty("quantity", t.getQuantityBought());
            o.addProperty("unitPrice", t.getBuyPrice());
            o.addProperty("totalCost", t.getTotalCost());
            o.addProperty("recordedAt", t.getBoughtAt().toString());
            o.addProperty("signature", t.getSourceKey());
            o.addProperty("soldQuantity", t.getQuantitySold());
            o.addProperty("saleRevenue", t.getSaleRevenue());
            o.addProperty("saleTax", t.getSaleTax());
            o.addProperty("lastSoldAt", t.getLastSoldAt() == null ? null : t.getLastSoldAt().toString());
            o.addProperty("lastActivityAt", t.getLastActivityAt().toString());
            o.addProperty("canceled", t.getStatus() == TradeTransaction.Status.CANCELED);
            o.addProperty("note", t.getNote());
            buys.add(o);
        }
        JsonArray sold = new JsonArray();
        for (RecordedSale sale : sales)
        {
            HistoryTrade t = sale.getTrade();
            JsonObject o = new JsonObject();
            o.addProperty("itemId", t.getItemId());
            o.addProperty("name", t.getItemName());
            o.addProperty("quantity", t.getQuantity());
            o.addProperty("net", t.getNetAmount());
            o.addProperty("gross", t.getGrossAmount());
            o.addProperty("tax", t.getTax());
            o.addProperty("recordedAt", t.getRecordedAt().toString());
            o.addProperty("note", sale.getNote());
            sold.add(o);
        }
        root.add("purchases", buys);
        root.add("sales", sold);
        configManager.setConfiguration(GROUP, KEY, gson.toJson(root));
    }

    public static final class LoadedData
    {
        public final List<TradeTransaction> purchases;
        public final List<RecordedSale> sales;

        LoadedData(List<TradeTransaction> purchases, List<RecordedSale> sales)
        {
            this.purchases = purchases;
            this.sales = sales;
        }
    }
}

package com.tradeledger;

import java.time.LocalDateTime;

public class TradeTransaction
{
    public enum Status { OPEN, COMPLETED, CANCELED }

    private final int itemId;
    private final String itemName;
    private final int quantityBought;
    private final int buyPrice;
    private final long totalCost;
    private final LocalDateTime boughtAt;
    private int quantitySold;
    private long saleRevenue;
    private long saleTax;
    private LocalDateTime lastSoldAt;
    private LocalDateTime lastActivityAt;
    private Status status = Status.OPEN;
    private Status statusBeforeCancellation = Status.OPEN;
    private String note = "";
    private String sourceKey = "";

    public TradeTransaction(int itemId, String itemName, int quantityBought, int buyPrice, LocalDateTime boughtAt)
    {
        this(itemId, itemName, quantityBought, buyPrice, (long) quantityBought * buyPrice, boughtAt);
    }

    public TradeTransaction(int itemId, String itemName, int quantityBought, int buyPrice, long totalCost, LocalDateTime boughtAt)
    {
        if (itemId <= 0 || itemName == null || itemName.isEmpty() || quantityBought <= 0 || buyPrice < 0 || totalCost < 0 || boughtAt == null)
        {
            throw new IllegalArgumentException("Invalid purchase transaction");
        }
        this.itemId = itemId;
        this.itemName = itemName;
        this.quantityBought = quantityBought;
        this.buyPrice = buyPrice;
        this.totalCost = totalCost;
        this.boughtAt = boughtAt;
        this.lastActivityAt = boughtAt;
    }

    /**
     * Record actual gross proceeds and an estimated GE tax for a partial fill.
     * Values are allocated exactly as supplied, without reconstructing them
     * from a rounded per-item average.
     */
    public void recordSaleTotals(int quantity, long gross, long tax, LocalDateTime soldAt)
    {
        if (status != Status.OPEN || quantity <= 0 || quantity > getQuantityRemaining()
            || gross < 0 || tax < 0 || tax > gross || soldAt == null)
        {
            throw new IllegalArgumentException("Invalid sale totals");
        }
        if (soldAt.isBefore(lastActivityAt))
        {
            throw new IllegalArgumentException("Sale timestamp precedes previous activity");
        }
        quantitySold += quantity;
        saleRevenue += gross;
        saleTax += tax;
        lastSoldAt = soldAt;
        lastActivityAt = soldAt;
        if (getQuantityRemaining() == 0)
        {
            status = Status.COMPLETED;
        }
    }

    public void recordSale(int quantity, int pricePerItem, long tax, LocalDateTime soldAt)
    {
        if (pricePerItem < 0)
        {
            throw new IllegalArgumentException("Invalid sale price");
        }
        recordSaleTotals(quantity, (long) quantity * pricePerItem, tax, soldAt);
    }

    public void restoreRecordedState(int soldQuantity, long grossRevenue, long tax, LocalDateTime soldAt, LocalDateTime activityAt, boolean canceled, String note)
    {
        if (soldQuantity < 0 || soldQuantity > quantityBought || grossRevenue < 0 || tax < 0)
        {
            throw new IllegalArgumentException("Invalid saved trade");
        }
        quantitySold = soldQuantity;
        saleRevenue = grossRevenue;
        saleTax = tax;
        lastSoldAt = soldAt;
        lastActivityAt = activityAt == null ? boughtAt : activityAt;
        status = soldQuantity == quantityBought ? Status.COMPLETED : Status.OPEN;
        statusBeforeCancellation = status;
        if (canceled)
        {
            status = Status.CANCELED;
        }
        this.note = note == null ? "" : note;
    }

    public void cancel()
    {
        if (status != Status.CANCELED)
        {
            statusBeforeCancellation = status;
            status = Status.CANCELED;
        }
    }

    public void restore()
    {
        if (status == Status.CANCELED)
        {
            status = statusBeforeCancellation;
        }
    }

    public int getItemId() { return itemId; }
    public String getItemName() { return itemName; }
    public int getQuantityBought() { return quantityBought; }
    public int getBuyPrice() { return buyPrice; }
    public LocalDateTime getBoughtAt() { return boughtAt; }
    public LocalDateTime getLastActivityAt() { return lastActivityAt; }
    public int getQuantitySold() { return quantitySold; }
    public int getQuantityRemaining() { return quantityBought - quantitySold; }
    public long getTotalCost() { return totalCost; }
    public long getRemainingCost() { return totalCost * getQuantityRemaining() / quantityBought; }
    public long getSaleRevenue() { return saleRevenue; }
    public long getSaleTax() { return saleTax; }
    public long getRealizedProfit() { return saleRevenue - saleTax - (totalCost - getRemainingCost()); }
    public LocalDateTime getLastSoldAt() { return lastSoldAt; }
    public Status getStatus() { return status; }
    public String getNote() { return note; }
    public void setNote(String note) { this.note = note == null ? "" : note; }
    public boolean isIncludedInOverview() { return status != Status.CANCELED; }
    public String getSourceKey() { return sourceKey; }
    public void setSourceKey(String sourceKey) { this.sourceKey = sourceKey == null ? "" : sourceKey; }
}

package com.tradeledger;

import java.awt.AlphaComposite;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Component;
import java.awt.Container;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.GridLayout;
import java.awt.RenderingHints;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.time.format.DateTimeFormatter;
import java.util.Locale;
import javax.swing.BorderFactory;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.ImageIcon;
import javax.swing.JLabel;
import javax.swing.JMenuItem;
import javax.swing.JPanel;
import javax.swing.JPopupMenu;
import javax.swing.SwingConstants;
import javax.swing.SwingUtilities;
import javax.swing.Timer;
import net.runelite.client.game.ItemManager;

public class TransactionCard extends JPanel
{
    private static final Color BACKGROUND = new Color(38, 38, 38);
    private static final Color OPEN_COLOR = new Color(55, 135, 225);
    private static final Color COMPLETED_COLOR = new Color(65, 165, 85);
    private static final Color CANCELED_COLOR = new Color(190, 65, 65);
    private static final Color MUTED_COLOR = new Color(190, 190, 190);

    private static final DateTimeFormatter DATE_FORMAT =
            DateTimeFormatter.ofPattern("dd MMM, HH:mm", Locale.ENGLISH);

    private static final float MAX_OVERLAY_OPACITY = 0.76f;
    private static final float ANIMATION_STEP = 0.12f;

    private final TradeTransaction transaction;
    private final Runnable cancelAction;
    private final Runnable restoreAction;
    private final Runnable deleteAction;
    private final Runnable editNoteAction;
    private final Runnable detailsAction;
    private final Runnable previewSaleAction;

    private final Timer fadeTimer;

    private float overlayOpacity;
    private float targetOpacity;

    public TransactionCard(
            TradeTransaction transaction,
            ItemManager itemManager,
            Runnable cancelAction,
            Runnable restoreAction,
            Runnable deleteAction,
            Runnable editNoteAction,
            Runnable detailsAction,
            Runnable previewSaleAction)
    {
        this.transaction = transaction;
        this.cancelAction = cancelAction;
        this.restoreAction = restoreAction;
        this.deleteAction = deleteAction;
        this.editNoteAction = editNoteAction;
        this.detailsAction = detailsAction;
        this.previewSaleAction = previewSaleAction;

        boolean inactive =
                transaction.getStatus() != TradeTransaction.Status.OPEN;

        overlayOpacity = inactive ? MAX_OVERLAY_OPACITY : 0.0f;
        targetOpacity = overlayOpacity;

        fadeTimer = new Timer(20, event -> animateOverlay());
        fadeTimer.setRepeats(true);

        setLayout(new BorderLayout(0, 13));
        setBackground(BACKGROUND);
        setAlignmentX(LEFT_ALIGNMENT);

        setBorder(
                BorderFactory.createCompoundBorder(
                        BorderFactory.createLineBorder(getStateColor(), 1),
                        BorderFactory.createEmptyBorder(12, 10, 13, 10)
                )
        );

        add(createHeader(itemManager), BorderLayout.NORTH);
        add(createStatistics(), BorderLayout.CENTER);

        installContextMenu(this);
        installHoverListeners(this);
    }

    private JPanel createHeader(ItemManager itemManager)
    {
        JPanel header = new JPanel(new BorderLayout(9, 0));
        header.setOpaque(false);

        JLabel iconLabel = new JLabel();
        iconLabel.setPreferredSize(new Dimension(40, 48));
        iconLabel.setHorizontalAlignment(SwingConstants.CENTER);

        if (itemManager != null)
        {
            iconLabel.setIcon(
                    new ImageIcon(itemManager.getImage(transaction.getItemId()))
            );
        }

        header.add(iconLabel, BorderLayout.WEST);

        JPanel textPanel = new JPanel();
        textPanel.setOpaque(false);
        textPanel.setLayout(new BoxLayout(textPanel, BoxLayout.Y_AXIS));

        JLabel nameLabel = new JLabel(transaction.getItemName());
        nameLabel.setForeground(Color.WHITE);
        TradeLedgerFonts.bold(nameLabel);
        nameLabel.setToolTipText(transaction.getItemName());

        JLabel dateLabel = new JLabel(
                "Bought: " + transaction.getBoughtAt().format(DATE_FORMAT)
        );
        dateLabel.setForeground(MUTED_COLOR);
        TradeLedgerFonts.regular(dateLabel);

        textPanel.add(nameLabel);
        textPanel.add(Box.createVerticalStrut(5));
        textPanel.add(dateLabel);

        if (transaction.getLastSoldAt() != null)
        {
            JLabel soldLabel = new JLabel(
                    "Sold: " + transaction.getLastSoldAt().format(DATE_FORMAT)
            );
            soldLabel.setForeground(MUTED_COLOR);
            TradeLedgerFonts.regular(soldLabel);

            textPanel.add(Box.createVerticalStrut(3));
            textPanel.add(soldLabel);
        }

        header.add(textPanel, BorderLayout.CENTER);

        installContextMenu(header);
        installContextMenu(iconLabel);
        installContextMenu(textPanel);
        installContextMenu(nameLabel);
        installContextMenu(dateLabel);

        for (Component child : textPanel.getComponents())
        {
            installContextMenu(child);
        }

        return header;
    }

    private JPanel createStatistics()
    {
        JPanel container = new JPanel();
        container.setOpaque(false);
        container.setLayout(new BoxLayout(container, BoxLayout.Y_AXIS));

        JPanel separator = new JPanel();
        separator.setBackground(new Color(80, 80, 80));
        separator.setAlignmentX(LEFT_ALIGNMENT);
        separator.setMaximumSize(
                new Dimension(Integer.MAX_VALUE, 1)
        );
        separator.setPreferredSize(new Dimension(1, 1));

        container.add(separator);
        container.add(Box.createVerticalStrut(12));

        JPanel statistics = new JPanel(new GridLayout(0, 2, 8, 16));
        statistics.setOpaque(false);
        statistics.setAlignmentX(LEFT_ALIGNMENT);

        addStatistic(
                statistics,
                "Quantity",
                formatNumber(transaction.getQuantityBought()),
                Color.WHITE,
                null
        );

        addStatistic(
                statistics,
                "Buy price",
                formatGp(transaction.getBuyPrice()),
                Color.WHITE,
                null
        );

        addStatistic(
                statistics,
                "Remaining",
                formatNumber(transaction.getQuantityRemaining()),
                Color.WHITE,
                null
        );

        addStatistic(
                statistics,
                "Total cost",
                formatCompactGp(transaction.getTotalCost()),
                Color.WHITE,
                formatGp(transaction.getTotalCost())
        );

        if (transaction.getQuantitySold() > 0)
        {
            addStatistic(
                    statistics,
                    "Sold",
                    formatNumber(transaction.getQuantitySold()),
                    Color.WHITE,
                    null
            );

            long profit = transaction.getRealizedProfit();

            addStatistic(
                    statistics,
                    "Realized profit",
                    formatSignedCompactGp(profit),
                    profit >= 0 ? COMPLETED_COLOR : CANCELED_COLOR,
                    formatSignedGp(profit)
            );
        }

        container.add(statistics);

        if (!transaction.getNote().isEmpty())
        {
            container.add(Box.createVerticalStrut(14));

            JLabel noteLabel = new JLabel(
                    "<html><body style='width:175px'>"
                            + escapeHtml(transaction.getNote())
                            + "</body></html>"
            );

            noteLabel.setForeground(MUTED_COLOR);
            TradeLedgerFonts.regular(noteLabel);
            noteLabel.setAlignmentX(LEFT_ALIGNMENT);

            container.add(noteLabel);
            installContextMenu(noteLabel);
        }

        installContextMenu(container);
        installContextMenu(statistics);

        return container;
    }

    private void addStatistic(
            JPanel parent,
            String title,
            String value,
            Color valueColor,
            String tooltip)
    {
        JPanel cell = new JPanel();
        cell.setOpaque(false);
        cell.setLayout(new BoxLayout(cell, BoxLayout.Y_AXIS));

        JLabel titleLabel = new JLabel(title);
        titleLabel.setForeground(MUTED_COLOR);
        TradeLedgerFonts.regular(titleLabel);

        JLabel valueLabel = new JLabel(value);
        valueLabel.setForeground(valueColor);
        TradeLedgerFonts.bold(valueLabel);

        if (tooltip != null)
        {
            valueLabel.setToolTipText(tooltip);
        }

        cell.add(titleLabel);
        cell.add(Box.createVerticalStrut(5));
        cell.add(valueLabel);

        parent.add(cell);

        installContextMenu(cell);
        installContextMenu(titleLabel);
        installContextMenu(valueLabel);
    }

    private void installHoverListeners(Component component)
    {
        MouseAdapter hoverListener = new MouseAdapter()
        {
            @Override
            public void mouseEntered(MouseEvent event)
            {
                updateHoverState(event);
            }

            @Override
            public void mouseExited(MouseEvent event)
            {
                updateHoverState(event);
            }

            @Override
            public void mouseMoved(MouseEvent event)
            {
                updateHoverState(event);
            }
        };

        component.addMouseListener(hoverListener);
        component.addMouseMotionListener(hoverListener);

        if (component instanceof Container)
        {
            Container container = (Container) component;

            for (Component child : container.getComponents())
            {
                installHoverListeners(child);
            }
        }
    }

    private void updateHoverState(MouseEvent event)
    {
        if (transaction.getStatus() == TradeTransaction.Status.OPEN)
        {
            return;
        }

        java.awt.Point point = SwingUtilities.convertPoint(
                event.getComponent(),
                event.getPoint(),
                this
        );

        boolean hovering = contains(point);

        float newTarget = hovering ? 0.0f : MAX_OVERLAY_OPACITY;

        if (targetOpacity != newTarget)
        {
            targetOpacity = newTarget;
            fadeTimer.start();
        }
    }

    private void animateOverlay()
    {
        if (Math.abs(overlayOpacity - targetOpacity) <= ANIMATION_STEP)
        {
            overlayOpacity = targetOpacity;
            fadeTimer.stop();
        }
        else if (overlayOpacity < targetOpacity)
        {
            overlayOpacity += ANIMATION_STEP;
        }
        else
        {
            overlayOpacity -= ANIMATION_STEP;
        }

        overlayOpacity = Math.max(
                0.0f,
                Math.min(MAX_OVERLAY_OPACITY, overlayOpacity)
        );

        repaint();
    }

    @Override
    protected void paintChildren(Graphics graphics)
    {
        super.paintChildren(graphics);

        if (overlayOpacity <= 0.0f ||
                transaction.getStatus() == TradeTransaction.Status.OPEN)
        {
            return;
        }

        Graphics2D graphics2D = (Graphics2D) graphics.create();

        try
        {
            graphics2D.setRenderingHint(
                    RenderingHints.KEY_ANTIALIASING,
                    RenderingHints.VALUE_ANTIALIAS_ON
            );

            int inset = 1;
            int width = getWidth() - 2 * inset;
            int height = getHeight() - 2 * inset;

            graphics2D.setComposite(
                    AlphaComposite.getInstance(
                            AlphaComposite.SRC_OVER,
                            overlayOpacity
                    )
            );

            graphics2D.setColor(Color.BLACK);
            graphics2D.fillRect(inset, inset, width, height);

            String statusText =
                    transaction.getStatus() == TradeTransaction.Status.COMPLETED
                            ? "COMPLETED"
                            : "CANCELED";

            Color statusColor =
                    transaction.getStatus() == TradeTransaction.Status.COMPLETED
                            ? COMPLETED_COLOR
                            : CANCELED_COLOR;

            float textOpacity = Math.min(
                    1.0f,
                    overlayOpacity / MAX_OVERLAY_OPACITY
            );

            graphics2D.setComposite(
                    AlphaComposite.getInstance(
                            AlphaComposite.SRC_OVER,
                            textOpacity
                    )
            );

            Font font = getFont().deriveFont(
                    Font.BOLD,
                    TradeLedgerFonts.STATUS_SIZE
            );
            graphics2D.setFont(font);

            FontMetrics metrics = graphics2D.getFontMetrics();

            int textWidth = metrics.stringWidth(statusText);
            int x = (getWidth() - textWidth) / 2;
            int y = (getHeight() + metrics.getAscent()
                    - metrics.getDescent()) / 2;

            graphics2D.setColor(new Color(10, 10, 10));
            graphics2D.drawString(statusText, x + 1, y + 2);

            graphics2D.setColor(statusColor);
            graphics2D.drawString(statusText, x, y);
        }
        finally
        {
            graphics2D.dispose();
        }
    }

    @Override
    public void removeNotify()
    {
        fadeTimer.stop();
        super.removeNotify();
    }

    private void installContextMenu(Component component)
    {
        component.addMouseListener(new MouseAdapter()
        {
            @Override
            public void mousePressed(MouseEvent event)
            {
                showMenuIfNeeded(event);
            }

            @Override
            public void mouseReleased(MouseEvent event)
            {
                showMenuIfNeeded(event);
            }

            private void showMenuIfNeeded(MouseEvent event)
            {
                if (event.isPopupTrigger())
                {
                    createContextMenu().show(
                            event.getComponent(),
                            event.getX(),
                            event.getY()
                    );
                }
            }
        });
    }

    private JPopupMenu createContextMenu()
    {
        JPopupMenu menu = new JPopupMenu();

        JMenuItem details = new JMenuItem("View details...");
        TradeLedgerFonts.regular(details);
        details.addActionListener(event -> detailsAction.run());
        menu.add(details);

        JMenuItem editNote = new JMenuItem("Edit note...");
        TradeLedgerFonts.regular(editNote);
        editNote.addActionListener(event -> editNoteAction.run());
        menu.add(editNote);

        if (previewSaleAction != null &&
                transaction.getStatus() == TradeTransaction.Status.OPEN)
        {
            JMenuItem simulateSale =
                    new JMenuItem("Simulate sale (demo)");

            TradeLedgerFonts.regular(simulateSale);
            simulateSale.addActionListener(
                    event -> previewSaleAction.run()
            );

            menu.add(simulateSale);
        }

        menu.addSeparator();

        if (transaction.getStatus() == TradeTransaction.Status.CANCELED)
        {
            JMenuItem restore = new JMenuItem("Restore trade");
            TradeLedgerFonts.regular(restore);
            restore.addActionListener(event -> restoreAction.run());
            menu.add(restore);
        }
        else
        {
            JMenuItem cancel = new JMenuItem("Cancel trade...");
            TradeLedgerFonts.regular(cancel);
            cancel.addActionListener(event -> cancelAction.run());
            menu.add(cancel);
        }

        JMenuItem delete = new JMenuItem("Remove from history...");
        TradeLedgerFonts.regular(delete);
        delete.addActionListener(event -> deleteAction.run());
        menu.add(delete);

        return menu;
    }

    private Color getStateColor()
    {
        switch (transaction.getStatus())
        {
            case COMPLETED:
                return COMPLETED_COLOR;
            case CANCELED:
                return CANCELED_COLOR;
            case OPEN:
            default:
                return OPEN_COLOR;
        }
    }

    private String formatNumber(long number)
    {
        return String.format(Locale.US, "%,d", number);
    }

    private String formatGp(long amount)
    {
        return formatNumber(amount) + " GP";
    }

    private String formatSignedGp(long amount)
    {
        return (amount >= 0 ? "+" : "") + formatGp(amount);
    }

    private String formatCompactGp(long amount)
    {
        long absolute = Math.abs(amount);

        if (absolute >= 1_000_000_000L)
        {
            return String.format(
                    Locale.US,
                    "%.2fb GP",
                    amount / 1_000_000_000.0
            );
        }

        if (absolute >= 1_000_000L)
        {
            return String.format(
                    Locale.US,
                    "%.2fm GP",
                    amount / 1_000_000.0
            );
        }

        if (absolute >= 100_000L)
        {
            return String.format(
                    Locale.US,
                    "%.1fk GP",
                    amount / 1_000.0
            );
        }

        return formatGp(amount);
    }

    private String formatSignedCompactGp(long amount)
    {
        return (amount >= 0 ? "+" : "") + formatCompactGp(amount);
    }

    private String escapeHtml(String value)
    {
        return value
                .replace("&", "&amp;")
                .replace("<", "&lt;")
                .replace(">", "&gt;")
                .replace("\"", "&quot;");
    }
}

